events.command:
/bin/bash -lc "find . -maxdepth 2 -type f -printf '%p\\n' | sort && printf '\\n--- binaries ---\\n' && command -v ffmpeg && command -v python3 && python3 - <<'PY'
mods=['cv2','PIL','numpy','torch','diffusers','imageio']
for m in mods:
 try:
  x=__import__(m); print(m,'OK',getattr(x,'__version__',''))
 except Exception as e: print(m,'NO',str(e)[:100])
PY"

/bin/bash -lc 'set +e
for x in python python3 ffmpeg convert magick; do printf "$x: "; command -v "$x" || true; done
python3 - <<'"'PY'
mods=['cv2','PIL','numpy','imageio','scipy','skimage']
